function menuItems(m,kind) {
  const cats=new Map(m.categories.map(c=>[c.id,c]));const items=[];
  const food=new Set(['FUERTES','RES','CERDO','AVES','PESCA','PASTAS','ARROCES','ARROCES Y PASTAS','SANDWICHES','SANDUCHES','BURGERS','BRUNCH','PANES ENTEROS']);
  for(const p of m.products){
    const cat=cats.get(p.product_category);if(!cat||p.disabled)continue;
    const chain=[];let cursor=cat;const seen=new Set();while(cursor&&!seen.has(cursor.id)){seen.add(cursor.id);chain.push(cursor);cursor=cats.get(cursor.hierarchy);}
    if(chain.some(c=>c.disabled||/PROMOCION|BANNER|VAPORIZADOR|VAPEADOR|HOOKAH|ADVERTENCIA/.test(norm(c.name))))continue;
    const section=norm(cat.name);let category;
    if(kind==='disco')category='drinks';
    else if(food.has(section))category='mains';
    else if(section==='POSTRES')category='desserts';
    else if(/ENTRADA|PARA COMPARTIR|TARDEO|SNACK|SOPA/.test(section))category='starters';
    else if(section==='ACOMPANAMIENTOS'||section==='EXTRAS'||section==='DESPENSA')category='extras';
    else if(kind==='absenta'||/BEBIDA|CAFE|JUGO/.test(section))category='drinks';
    else continue;
    const prices=Array.isArray(p.price)?p.price:typeof p.price==='object'?[p.price]:[{price:p.price,label:''}];
    for(const v of prices){if(v.disable||v.noStock||!Number.isFinite(Number(v.price))||Number(v.price)<=0)continue;
      const item={name:p.product_name.trim(),category,presentation:[v.label?.trim(),cat.name.trim()].filter(Boolean).join(' · '),price:Number(v.price),currency:'COP',sourceUrl:m.source,sourceProductId:p.id,menuSection:cat.name.trim(),verifiedAt:now,calculationIncluded:true};
      const collision=items.find(i=>i.name===item.name&&i.category===item.category&&i.presentation===item.presentation);
      if(collision){if(collision.price!==item.price)collision.calculationIncluded=false;continue;}items.push(item);
    }
  }return items;
}
function reference(items,name,section,variant='',quantity=1,groupSize=1){const presentation=[variant,section].filter(Boolean).join(' · ');const m=items.filter(i=>i.name===name&&i.presentation===presentation&&i.calculationIncluded!==false);assert.equal(m.length,1,`Missing reviewed product ${name}: ${presentation}`);return {name,category:m[0].category,presentation,quantity,groupSize};}
function budgets(items,scenarios){const amounts=scenarios.map(s=>s.lines.reduce((n,l)=>n+items.find(i=>i.name===l.name&&i.category===l.category&&i.presentation===l.presentation).price*Math.ceil(2/l.groupSize)*l.quantity,0)/2);assert.ok(amounts[0]<amounts[1]&&amounts[1]<amounts[2],'Budgets must increase for two people');return {menu_items:items,budget_scenarios:scenarios,min_budget:amounts[0],typical_budget:amounts[0],max_budget:amounts[2],budget_basis:scenarios[0].concept,menu_items_verified_at:now,menu_calculation_note:'Propuestas de consumo, no promedios. El restaurante puede actualizar los precios. No incluye propina ni cover no confirmado.'};}
